import 'dart:async';

import 'package:flutter/material.dart';
import 'package:fpdart/fpdart.dart' hide State;
import 'package:go_router/go_router.dart';

import 'core/di/injection_container.dart';
import 'core/failure/failure.dart';
import 'core/navigation/app_router.dart';
import 'core/navigation/expiry_overlay_host.dart';
import 'features/auth/domain/repositories/session_repository.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try {
    await setupCoreDependencies();
  } catch (error) {
    debugPrint(
      'Cerne failed to start: could not load .env ($error). Copy '
      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
      'SUPABASE_ANON_KEY before running the app.',
    );
    rethrow;
  }
  runApp(const CerneApp());
}

/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
/// breakpoint, landscape or dark-mode path anywhere in the app (per the
/// epic's UX constraints; the portrait lock itself lives in
/// `ios/Runner/Info.plist`, Story 1.6).
///
/// Story 1.6 scope: the ad-hoc `StreamBuilder`/`Navigator.push` shell
/// Stories 1.3-1.5 built this on top of is replaced by the one real
/// `go_router` (`core/navigation/app_router.dart`) plus its
/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
/// here (unchanged from Story 1.4), but every screen transition and the
/// expiry overlay's own "Entrar novamente" now go through that router
/// instead of an imperative `Navigator`.
class CerneApp extends StatefulWidget {
  const CerneApp({super.key});

  @override
  State<CerneApp> createState() => _CerneAppState();
}

class _CerneAppState extends State<CerneApp> {
  late final SessionRepository _sessionRepository;
  late final GoRouter _router;

  // Created here (not left for `GoRouter` to generate internally) and
  // passed to both `buildAppRouter` and `ExpiryOverlayHost` below, so the
  // latter can reach the Navigator's own `BuildContext` through this
  // public, documented key instead of reaching into `GoRouter`'s internal
  // `routerDelegate`.
  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>(
    debugLabel: 'root',
  );

  @override
  void initState() {
    super.initState();
    _sessionRepository = sl<SessionRepository>();
    _router = buildAppRouter(
      sessionRepository: _sessionRepository,
      navigatorKey: _navigatorKey,
    );
    // Fire-and-forget: the outcome reaches the UI through
    // `SessionRepository.currentStatus`/`statusStream` (which the router's
    // `redirect`/`refreshListenable` already watch), not through this
    // call's return value. `restoreSession()` already maps every internal
    // failure to `Left`/an `unauthenticated` emission and never throws.
    // This `catchError` is NOT a UI recovery path — its handler's return
    // value is discarded by `unawaited` and never reaches `statusStream`.
    // It exists purely so a future regression that broke the "never
    // throws" contract above would surface as a logged message instead of
    // an unhandled zone exception.
    unawaited(
      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
    );
  }

  @override
  void dispose() {
    _router.dispose();
    super.dispose();
  }

  // `catchError`'s handler must still complete the Future with a value of
  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
  // handler would try to complete it with `null`, which isn't assignable
  // to that non-nullable type and would itself throw.
  static Either<Failure, Unit> _asUnauthenticated(
    Object error,
    StackTrace stackTrace,
  ) {
    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
    return left(Failure.malformedResponse(message: error.toString()));
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp.router(
      debugShowCheckedModeBanner: false,
      routerConfig: _router,
      builder: (context, child) => ExpiryOverlayHost(
        sessionRepository: _sessionRepository,
        router: _router,
        navigatorKey: _navigatorKey,
        child: child!,
      ),
    );
  }
}

import 'package:freezed_annotation/freezed_annotation.dart';

part 'failure.freezed.dart';

/// AD-3 — the one closed `Failure` hierarchy, exactly 14 subtypes: the 13
/// codes from `docs/input/backend/error-taxonomy.md` plus the local-only
/// `malformedResponse` (client-side parse failure, never sent by the
/// backend). Never redefined or subset per feature; every repository method
/// returns `Either<Failure, T>` built from this type (RNF09).
///
/// `retryable` is derived here, once, from the 6 server `retryable:true`
/// codes (AD-4) — no other file re-decides which codes retry.
@freezed
sealed class Failure with _$Failure {
  const factory Failure.authExpired({required String message}) = AuthExpired;
  const factory Failure.authInvalid({required String message}) = AuthInvalid;
  const factory Failure.networkTimeout({required String message}) =
      NetworkTimeout;
  const factory Failure.networkOffline({required String message}) =
      NetworkOffline;
  const factory Failure.validation({required String message}) = Validation;
  const factory Failure.piiCheckFailed({required String message}) =
      PiiCheckFailed;
  const factory Failure.embeddingFailed({required String message}) =
      EmbeddingFailed;
  const factory Failure.aiGenerationTimeout({required String message}) =
      AiGenerationTimeout;
  const factory Failure.notFound({required String message}) = NotFound;
  const factory Failure.rateLimited({required String message}) = RateLimited;
  const factory Failure.exportEmptyPeriod({required String message}) =
      ExportEmptyPeriod;
  const factory Failure.payloadTooLarge({required String message}) =
      PayloadTooLarge;
  const factory Failure.ocrNoText({required String message}) = OcrNoText;

  /// Local-only — the client's own parse-failure detection. `retryable` is
  /// hardcoded `false` for this subtype (AD-3).
  const factory Failure.malformedResponse({required String message}) =
      MalformedResponse;

  const Failure._();

  /// The 6 server `retryable:true` codes (AD-4). Every other code —
  /// including the local `malformedResponse` — is `false`.
  bool get retryable => switch (this) {
        NetworkTimeout() => true,
        NetworkOffline() => true,
        PiiCheckFailed() => true,
        EmbeddingFailed() => true,
        AiGenerationTimeout() => true,
        RateLimited() => true,
        AuthExpired() ||
        AuthInvalid() ||
        Validation() ||
        NotFound() ||
        ExportEmptyPeriod() ||
        PayloadTooLarge() ||
        OcrNoText() ||
        MalformedResponse() =>
          false,
      };

  /// Maps a backend error `code` (`error-taxonomy.md`) to its `Failure`
  /// subtype. An unrecognized code (should never happen — the taxonomy is
  /// closed) falls back to [Failure.malformedResponse] rather than throwing,
  /// so no repository ever lets an unmapped error escape (RNF09).
  factory Failure.fromCode(String code, String message) => switch (code) {
        'AUTH_EXPIRED' => Failure.authExpired(message: message),
        'AUTH_INVALID' => Failure.authInvalid(message: message),
        'NETWORK_TIMEOUT' => Failure.networkTimeout(message: message),
        'NETWORK_OFFLINE' => Failure.networkOffline(message: message),
        'VALIDATION_ERROR' => Failure.validation(message: message),
        'PII_CHECK_FAILED' => Failure.piiCheckFailed(message: message),
        'EMBEDDING_FAILED' => Failure.embeddingFailed(message: message),
        'AI_GENERATION_TIMEOUT' =>
          Failure.aiGenerationTimeout(message: message),
        'NOT_FOUND' => Failure.notFound(message: message),
        'RATE_LIMITED' => Failure.rateLimited(message: message),
        'EXPORT_EMPTY_PERIOD' => Failure.exportEmptyPeriod(message: message),
        'PAYLOAD_TOO_LARGE' => Failure.payloadTooLarge(message: message),
        'OCR_NO_TEXT' => Failure.ocrNoText(message: message),
        _ => Failure.malformedResponse(message: message),
      };
}

