539	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
540	/// requires. Covers the I/O matrix (spec-2-1):
541	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
542	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
543	///   `false`, or throws `LocalAuthException`) -> status stays
544	///   [VaultStatus.locked], `Left(Failure.malformedResponse(...))`.
545	///
546	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
547	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
548	/// reserved for password login) — both the `false` and the thrown-exception
549	/// branches below map only to [Failure.malformedResponse].
550	class VaultRepositoryImpl implements VaultRepository {
551	  VaultRepositoryImpl({required LocalAuthentication localAuthentication})
552	    : _localAuthentication = localAuthentication;
553	
554	  final LocalAuthentication _localAuthentication;
555	  final StreamController<VaultStatus> _statusController =
556	      StreamController<VaultStatus>.broadcast();
557	
558	  /// The last status emitted. Starts at [VaultStatus.locked] — not
559	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
560	  /// synchronously from construction, with no async warm-up step.
561	  VaultStatus _lastStatus = VaultStatus.locked;
562	
563	  @override
564	  VaultStatus get currentStatus => _lastStatus;
565	
566	  @override
567	  Stream<VaultStatus> get statusStream {
568	    // Same `Stream.multi` replay-to-late-listeners rationale as
569	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
570	    // after construction (but before any [authenticate] call) still
571	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
572	    // rather than nothing until the next emission.
573	    return Stream<VaultStatus>.multi((controller) {
574	      controller.add(_lastStatus);
575	      final subscription = _statusController.stream.listen(
576	        controller.add,
577	        onError: controller.addError,
578	        onDone: controller.close,
579	      );
580	      controller.onCancel = subscription.cancel;
581	    }, isBroadcast: true);
582	  }
583	
584	  void _emit(VaultStatus status) {
585	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
586	    // an in-flight `authenticate()` call — mirrors
587	    // `SessionRepositoryImpl._emit`'s own guard.
588	    if (_statusController.isClosed) {
589	      return;
590	    }
591	    _lastStatus = status;
592	    _statusController.add(status);
593	  }
594	
595	  @override
596	  Future<Either<Failure, Unit>> authenticate() async {
597	    try {
598	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
599	      // OS's own device-passcode UI satisfy this call, which would bypass
600	      // Cerne's own PIN screen (Story 2.2) entirely.
601	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
602	      // (e.g. an incoming call) retries on foreground instead of failing
603	      // outright.
604	      final success = await _localAuthentication.authenticate(
605	        localizedReason: 'Autentique-se para acessar o Cerne',
606	        biometricOnly: true,
607	        persistAcrossBackgrounding: true,
608	      );
609	      if (success) {
610	        _emit(VaultStatus.unlocked);
611	        return right(unit);
612	      }
613	      // A `false` result (declined/unavailable, no exception) — status
614	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
615	      // for password login).
616	      return left(
617	        const Failure.malformedResponse(
618	          message: 'Biometric authentication was not successful',
619	        ),
620	      );
621	    } on LocalAuthException catch (error) {
622	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
623	      // etc. (RNF09: never let a platform exception escape unmapped).
624	      return left(Failure.malformedResponse(message: error.toString()));
625	    }
626	  }
